// Fim dos Tempos · Arco 2 · O Labirinto Liberto · gerado por a2-labirinto-liberto.js
const DADOS = {"pericias":{"inve":"Investigação","perc":"Percepção","conh":"Conhecimento","reli":"Religião","mist":"Misticismo","sobr":"Sobrevivência","nobr":"Nobreza","dipl":"Diplomacia","enga":"Enganação","inti":"Intimidação","ladi":"Ladinagem","furt":"Furtividade","atle":"Atletismo","guer":"Guerra","joga":"Jogatina","intu":"Intuição","cura":"Cura","ofic":"Ofício"},"entradas":{"hyninn":{"nome":"Entrada de Hyninn","chegada":"Área de Entrada A (Sala 1 de Hyninn)","texto":"Uma rachadura na estátua leva a um túnel e a uma antessala quadrada e exígua, totalmente escura, com uma porta de ferro e pedra e duas estátuas esguias. Uma delas diz: <i>\"Fomos colocados aqui por todos os deuses do Panteão. Nossa missão é guardar o Labirinto Liberto. Somos opostos, pois um de nós sempre fala a verdade. Vocês podem fazer apenas uma pergunta para cada um de nós. Se apontarem aquele que sempre fala a verdade, poderão passar.\"</i>","dica":"As feições das estátuas são alongadas: focinhos de raposa.","solucao":"Tudo que a estátua disse é mentira: foram esculpidas por devotos de Hyninn, não são opostas, nenhuma fala a verdade, dá para perguntar quanto quiser e apontar a \"verdadeira\" não abre nada. A solução é contrariar as regras e <b>arrombar a porta</b> (porta de ferro: Defesa 8, RD 10, 100 PV, Ladinagem CD 30). Grupos respeitosos e solenes, que nunca desafiam as estátuas, não passam."},"tanna":{"nome":"Entrada de Tanna-Toh","chegada":"Área de Entrada B (Sala 1 de Tanna-Toh)","texto":"A porta de uma casa num beco vira um túnel de quilômetros até uma câmara quadrada com paredes, chão e teto cobertos de escritos antigos (Conhecimento CD 30 ou Compreensão: língua antiga de Lamnor, a história da Rainha Barda que trouxe a escrita). No centro, uma enorme corneta de bronze, muda. Em valkar, no meio das palavras: <b>SOME GRANDE FOGO / RECUSE SEUS PRIMEIROS</b>.","dica":"Os escritos cobrem todas as superfícies: é um lugar do conhecimento. Religião percebe que \"some grande fogo\" não tem significado religioso.","solucao":"É um anagrama, e nenhum meio mágico o resolve: <b>CONFESSEM UM SEGREDO E IRÃO PROSSEGUIR</b>. Cada personagem fala um segredo sobre si em voz alta dentro da corneta; quando todos falarem, uma parede se abre. Se o grupo achar chato, permita um teste estendido; ou tente outra entrada."},"azgher":{"nome":"Entrada de Azgher","chegada":"Área de Entrada C (Sala 1 de Azgher)","texto":"Uma boca de lobo numa ruela escura vira uma passagem cada vez mais larga e clara. Em quase uma hora, um salão iluminado pelo ouro das decorações, hieróglifos e um sol imenso. Uma balança de ouro pende por causa de uma pedra escura e opaca; aos pés, uma bandeja de pepitas. A inscrição: <i>\"Nenhum mortal está livre do pecado aos olhos de Azgher. Cada um deve confessar um pecado único. Juntos, todos os pecados devem se equilibrar com toda a escuridão que existe em Arton.\"</i>","dica":"O que parece um símbolo de Khalmyr (a balança) é de Azgher: pecados contra as Obrigações & Restrições do Deus-Sol.","solucao":"Religião CD 20 revela o sentido e a lista de pecados (sem os pontos). Cada personagem confessa uma quebra das O&R de Azgher (mesmo sem ser devoto) e põe uma pepita. Cada pecado só pode ser confessado uma vez. Leve vale 1, médio 2, grave 3; a balança equilibra com <b>10 pontos</b>. Lado mais pesado: pedras escuras e opacas; mais leve: douradas; equilibrada: ambas cinzentas e reluzentes, e o sol se desfaz num mecanismo que revela a entrada."}}};
(async function macroBusca(D) {
		const ESTADO = "fdtLabirinto";
		const b = foundry.utils.deepClone(game.user.getFlag("world", `${ESTADO}.busca`) ?? { sucessos: 0, falhas: 0, testes: 0, usadas: [] });
		const atores = canvas.tokens.controlled.map((t) => t.actor).filter(Boolean);
		const cd = 20 + 2 * b.testes;
		const opPer = Object.entries(D.pericias).map(([k, n]) => {
			const usada = k !== "inve" && b.usadas.includes(k);
			return `<option value="${k}" ${usada ? "disabled" : ""}>${n}${usada ? " (já usada)" : ""}</option>`;
		}).join("");
		const opEnt = Object.entries(D.entradas).map(([k, e]) => `<option value="${k}">${e.nome}</option>`).join("");
		const res = await foundry.applications.api.DialogV2.prompt({
			window: { title: "Labirinto · Busca pela Entrada" },
			position: { width: 500 },
			content: `
				<p>Teste estendido aberto: <b>7 sucessos</b> antes de 3 falhas. CD atual <b>${cd}</b> (20, +2 por teste). Progresso: <b>${b.sucessos}/7</b>, ${b.falhas} falha(s), ${b.testes} teste(s) = ${(b.testes / 2).toFixed(1)} dia(s).
				Só Investigação pode repetir. Cada falha custa 1d4 PM, que só voltam ao achar a entrada ou ao fim da aventura.</p>
				<div class="form-group"><label>O que aconteceu</label><select name="acao">
					<option value="rolar">Rolar (o primeiro token selecionado faz o teste)</option>
					<option value="npc">Um NPC que conhece o Labirinto ajudou (1 sucesso)</option>
					<option value="avatar">O Avatar da Cidade colaborou (3 sucessos)</option>
					<option value="zerar">Zerar o progresso</option></select></div>
				<div class="form-group"><label>Perícia</label><select name="per">${opPer}</select></div>
				<div class="form-group"><label>Bônus (ajuda, ideias)</label><input type="number" name="mod" value="0"></div>
				<div class="form-group"><label>Falha custa PM a todos os selecionados</label><input type="checkbox" name="todos"></div>
				<div class="form-group"><label>Entrada que o grupo procura</label><select name="entrada">${opEnt}</select></div>
				<div class="form-group"><label>Rolar um encontro em Valkaria</label><input type="checkbox" name="encontro"></div>`,
			ok: { label: "Aplicar", callback: (ev, button) => Object.fromEntries(new FormData(button.form)) }
		});
		if (!res) return;
		if (res.acao === "zerar") return game.user.unsetFlag("world", `${ESTADO}.busca`);
		const rolls = [];
		let html = "<h3>Busca pelo Labirinto Liberto</h3>";
		if (res.acao === "rolar") {
			const a = atores[0];
			if (!a) return ui.notifications.warn("Selecione o token de quem faz o teste (e, se quiser, o resto do grupo).");
			const bonus = (k) => {
				if (k === "ofic") return Math.max(0, ...Object.entries(a.system.pericias ?? {}).filter(([kk]) => kk.startsWith("ofi") || kk === "alqu").map(([, v]) => Number(v?.value) || 0));
				return Number(a.system.pericias?.[k]?.value) || 0;
			};
			const r = await new Roll(`1d20 + ${bonus(res.per)} + ${Number(res.mod) || 0}`).evaluate();
			rolls.push(r);
			const ok = r.total >= cd;
			b.testes++;
			if (res.per !== "inve" && !b.usadas.includes(res.per)) b.usadas.push(res.per);
			html += `<p>${a.name} · ${D.pericias[res.per]} <b>${r.total}</b> contra CD ${cd}: ${ok ? "✔️ sucesso" : "❌ falha"}</p>`;
			if (ok) b.sucessos++;
			else {
				b.falhas++;
				for (const x of res.todos ? atores : [a]) {
					const d = await new Roll("1d4").evaluate();
					rolls.push(d);
					await x.update({ "system.attributes.pm.value": Math.max(0, (Number(x.system.attributes.pm?.value) || 0) - d.total) });
					html += `<p>${x.name} perde <b>${d.total} PM</b> (esforço e frustração).</p>`;
				}
			}
		} else {
			const n = res.acao === "avatar" ? 3 : 1;
			b.testes++;
			b.sucessos += n;
			html += `<p>${res.acao === "avatar" ? "O Avatar da Cidade colabora" : "Um NPC que conhece o Labirinto ajuda"}: <b>${n} sucesso(s)</b>.</p>`;
		}
		if (b.falhas >= 3 && b.sucessos < 7) {
			html += "<h4>Falha total</h4><p>Três falhas antes dos 7 sucessos: os personagens ficam <b>alquebrados</b> até acharem a entrada ou até o fim da aventura, e o teste recomeça do zero.</p>";
			for (const x of atores) await x.toggleStatusEffect("alquebrado", { active: true });
			await game.user.unsetFlag("world", `${ESTADO}.busca`);
		} else if (b.sucessos >= 7) {
			const e = D.entradas[res.entrada];
			html += `<h4>Entrada encontrada!</h4><p><b>${e.nome}.</b> ${e.texto}</p><p style="font-size:0.85em">Os PM perdidos na busca voltam agora. Use <i>Labirinto · Entradas</i> para o desafio.</p>`;
			await game.user.unsetFlag("world", `${ESTADO}.busca`);
		} else {
			html += `<p>Progresso: <b>${b.sucessos}/7</b>, ${b.falhas}/3 falha(s), ${(b.testes / 2).toFixed(1)} dia(s).</p>`;
			await game.user.setFlag("world", `${ESTADO}.busca`, b);
		}
		await ChatMessage.create({ content: html, rolls, whisper: ChatMessage.getWhisperRecipients("GM") });
		if (res.encontro) {
			const t = game.tables.find((x) => x.name === "Encontros em Valkaria");
			if (t) return t.draw();
			ui.notifications.info("Role um encontro em Valkaria (tabela da Aventura 0).");
		}
	})(DADOS);
